<script setup lang="ts">
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ListPanel from '../components/ListPanel.vue';
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { Search } from 'lucide-vue-next';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import { activationUrl, dateText, downloadMaterial, errorText, kindText, moduleNames, moduleText, post, statusText } from '../saas';
import '../saas.css';
const session=useSessionStore();const canManage=computed(()=>session.user?.permissions.includes('system:organization:update')??false);
const rows=ref<any[]>([]);const total=ref(0);const page=ref(1);const q=ref('');const status=ref('');const loading=ref(false);const error=ref('');const selected=ref<any>(null);const dialog=ref(false);const saving=ref(false);const result=ref<any>(null);const review=reactive({action:'APPROVE',comment:'',modules:[] as string[],validUntil:'',vehicleQuota:1000});
async function load(){loading.value=true;error.value='';try{const r=await api<any>(`/saas/applications?${new URLSearchParams({...(q.value.trim()?{q:q.value.trim()}:{}),...(status.value?{status:status.value}:{}),page:String(page.value),pageSize:'20'})}`);rows.value=r.items;total.value=r.total}catch(e){error.value=errorText(e)}finally{loading.value=false}}
function search(){page.value=1;load()}
function open(row:any){selected.value=row;result.value=null;Object.assign(review,{action:'APPROVE',comment:'',modules:[...(row.modules??[])],validUntil:'',vehicleQuota:Math.max(row.expectedVehicles??100,1000)});dialog.value=true}
async function submit(){if(review.comment.trim().length<2)return ElMessage.warning('请填写至少2字的审核意见');if(review.action==='APPROVE'&&!review.modules.length)return ElMessage.warning('请至少批准一个业务模块');saving.value=true;try{result.value=await post(`/saas/applications/${selected.value.id}/review`,{action:review.action,comment:review.comment,modules:review.modules,validUntil:review.validUntil||undefined,quotas:{vehicles:review.vehicleQuota}});selected.value=result.value.application??selected.value;ElMessage.success('审核决定已保存');await load();if(review.action!=='APPROVE')dialog.value=false}catch(e){ElMessage.error(errorText(e))}finally{saving.value=false}}
async function provision(){saving.value=true;try{result.value=await post(`/saas/applications/${selected.value.id}/provision`);await load()}catch(e){ElMessage.error(errorText(e))}finally{saving.value=false}}
async function download(material:any){try{await downloadMaterial(selected.value.id,material)}catch(e){ElMessage.error(errorText(e))}}
async function copy(){try{await navigator.clipboard.writeText(activationUrl(result.value.invitation));ElMessage.success('激活链接已复制，请交付给申请指定负责人')}catch{ElMessage.warning('浏览器未允许复制，请手动复制下方链接')}}
onMounted(load);

function resetQueryFilters() {
  q.value = '';
  status.value = '';
  page.value = 1;
  search();
}
</script>
<template><div class="saas-page"><h1 class="sr-only">市级开通申请</h1><QueryPanel :loading="loading" @search="search" @reset="resetQueryFilters">
<QueryField label="关键词" keyword><el-input v-model="q" :prefix-icon="Search" clearable placeholder="搜索城市、申请单位或编号" aria-label="搜索开通申请" /></QueryField>
<QueryField label="申请状态"><el-select v-model="status" clearable placeholder="全部状态" aria-label="申请状态" @change="search"><el-option v-for="s in ['SUBMITTED','RETURNED','APPROVED','REJECTED','WITHDRAWN']" :key="s" :label="statusText(s)" :value="s"/></el-select></QueryField>
</QueryPanel>
<ListPanel title="开通申请列表" :total="error ? undefined : (total)">
<div v-if="error" class="saas-error" role="alert"><span>{{error}}</span><el-button @click="load">重试</el-button></div><el-table v-else v-loading="loading" :data="rows" row-key="id" empty-text="没有符合条件的开通申请"><el-table-column prop="businessNo" label="申请编号" min-width="190"/><el-table-column prop="cityName" label="城市" width="100"/><el-table-column label="申请事项" width="110"><template #default="{row}">{{kindText(row.kind)}}</template></el-table-column><el-table-column prop="unitName" label="申请单位" min-width="200"/><el-table-column label="申请模块" min-width="200"><template #default="{row}">{{moduleText(row.modules)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='REJECTED'?'danger':row.status==='APPROVED'?'success':'info'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="提交时间" min-width="170"><template #default="{row}">{{dateText(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button text type="primary" @click="open(row)">{{row.status==='SUBMITTED'&&canManage?'审核':'查看'}}</el-button></template></el-table-column></el-table><el-pagination v-if="total" v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load"/>

</ListPanel>
<el-dialog v-model="dialog" :title="`${selected?.cityName??''} · ${kindText(selected?.kind)}`" width="720" destroy-on-close><template v-if="selected"><el-descriptions :column="2" border class="saas-dialog-info"><el-descriptions-item label="申请单位" :span="2">{{selected.unitName}}</el-descriptions-item><el-descriptions-item label="联系人">{{selected.contactName}}</el-descriptions-item><el-descriptions-item label="联系电话">{{selected.contactPhone}}</el-descriptions-item><el-descriptions-item label="管理员">{{selected.adminName}}</el-descriptions-item><el-descriptions-item label="管理员账号">{{selected.adminUsername}}</el-descriptions-item><el-descriptions-item label="预计车辆">{{selected.expectedVehicles}}</el-descriptions-item><el-descriptions-item label="当前状态">{{statusText(selected.status)}}</el-descriptions-item><el-descriptions-item label="材料摘要" :span="2">{{selected.materialNote}}</el-descriptions-item></el-descriptions><div v-if="selected.materials?.length" class="saas-panel" style="margin-bottom:16px"><h2>申请附件</h2><div v-for="material in selected.materials" :key="material.id" class="saas-heading"><span>{{material.originalName||material.name}}</span><el-button text type="primary" @click="download(material)">下载核验</el-button></div></div><el-form v-if="selected.status==='SUBMITTED'&&canManage" label-position="top"><el-form-item label="审核决定"><el-radio-group v-model="review.action"><el-radio value="APPROVE">批准开通</el-radio><el-radio value="RETURN">退回补正</el-radio><el-radio value="REJECT">驳回申请</el-radio></el-radio-group></el-form-item><template v-if="review.action==='APPROVE'"><el-form-item label="批准模块"><el-checkbox-group v-model="review.modules"><el-checkbox v-for="(name,code) in moduleNames" :key="code" :value="code">{{name}}</el-checkbox></el-checkbox-group></el-form-item><div class="saas-grid"><el-form-item label="授权有效期"><el-date-picker v-model="review.validUntil" type="date" value-format="YYYY-MM-DDTHH:mm:ss.SSS[Z]" placeholder="不填则长期有效"/></el-form-item><el-form-item label="车辆配额"><el-input-number v-model="review.vehicleQuota" :min="1" :max="1000000"/></el-form-item></div></template><el-form-item label="审核意见" required><el-input v-model="review.comment" type="textarea" :rows="3" maxlength="2000" aria-label="审核意见"/></el-form-item></el-form><p v-else class="saas-subtle">审核意见：{{selected.reviewComment||'—'}}</p><template v-if="result"><el-alert :title="`开通执行：${statusText(result.job?.status)}`" :type="result.job?.status==='FAILED'?'error':'success'" :closable="false" :description="result.job?.error"/><div v-if="result.invitation?.activationToken" class="saas-credential-box"><strong>管理员激活邀请已生成</strong><p>请将链接交付给申请指定负责人。平台尚未向外部渠道发送通知。</p><div class="saas-secret">{{activationUrl(result.invitation)}}</div><el-button style="margin-top:10px" @click="copy">复制激活链接</el-button></div></template><el-button v-if="selected.status==='APPROVED'&&!result?.invitation&&canManage" :loading="saving" style="margin-top:16px" @click="provision">执行或重试开通</el-button></template><template #footer><el-button @click="dialog=false">关闭</el-button><el-button v-if="selected?.status==='SUBMITTED'&&canManage" type="primary" :loading="saving" @click="submit">保存审核决定</el-button></template></el-dialog></div></template>
